import React, { useEffect } from 'react';

export default function AboutMe({ theme }) {
  useEffect(() => {
    // once the badge div is in the DOM, tell LinkedIn to render it
    if (window.IN && typeof window.IN.parse === 'function') {
      window.IN.parse();
    }
  }, []);

  return (
    <section id="about" className="py-12">
      <h2 className={`text-2xl font-bold mb-6 ${
        theme === 'dark' ? 'text-yellow-400' : 'text-blue-800'
      }`}>
        About Me
      </h2>
      <div className="grid md:grid-cols-2 gap-8 items-start">
        {/* Your bio text… */}
        <div className={`
          space-y-4
          ${theme === 'dark' ? 'text-yellow-300' : 'text-blue-600'}
        `}>
          <p>
            I’m a Running Start student at SPSCC pursuing an A.A. in Computer Science and an
            aspiring Electrical & Computer Engineer…
          </p>
          <p>
            As captain of FRC Team 4450, I restructured leadership and ran rookie workshops;…
          </p>
        </div>

        {/* LinkedIn badge */}
        <div>
          <div
            className="LI-profile-badge"
            data-version="v1"
            data-size="medium"
            data-locale="en_US"
            data-type="inline"
            data-theme={theme === 'dark' ? 'dark' : 'light'}
            data-vanity="srivikaatr"
          >
            <a
              className="LI-simple-link"
              href="https://www.linkedin.com/in/srivikaatr?trk=profile-badge"
            >
              Srivikaat Ravi
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}
